 {page==='condition'&&<MobileAnalysis><div className="grid"><Panel title="現在の学習状態" variant="summary"><div className="inline-ring"><Ring score={current.condition}/><div><h3>{A.label(current.condition,{...A.defaults,...d.settings})}</h3><p>信頼度 {current.confidence}</p><p>目標 {d.goals.site.learning_condition_target??'—'} / 100</p>{current.condition===null&&<p className="muted">{current.reason}</p>}</div></div><Stats items={[["前週比",diff(current.condition,prev.condition)],['Balance',pt(current.balance),diff(current.balance,prev.balance)],['Stability',pt(current.stability),diff(current.stability,prev.stability)]]}/><div className="actions"><button onClick={()=>go('balance')}>Balanceの詳細</button><button onClick={()=>go('stability')}>Stabilityの詳細</button></div></Panel><Panel mobileSection="analysis" title="4週間のスコア推移"><ScoreChart history={history.slice(-4)}/></Panel></div><Panel mobileSection="analysis" title="スコア変動要因"><GridTable heads={['要因','総合点への寄与の変化']} rows={[["科目比率・追加減点",diff(current.balance===null?null:current.balance*(d.settings?.balanceWeight??.4),prev.balance===null?null:prev.balance*(d.settings?.balanceWeight??.4))],...(['time','zero','continuity'] as const).map((k,i)=>{const weight=[d.settings?.timeWeight??.7,d.settings?.zeroWeight??.2,d.settings?.continuityWeight??.1][i]*(d.settings?.stabilityWeight??.6);return [['日別ばらつき','0時間日','科目継続性'][i],current.condition===null||prev.condition===null?'比較データ不足':diff(current[k]*weight,prev[k]*weight)];})]}/></Panel><Simulation mobileSection="details" d={d} date={date} current={current}/><Panel mobileSection="details" collapsible title="スコア履歴" subtitle="保存時点の点数と理由。上の推移は現在の設定で再計算。"><GridTable heads={['日時','総合','Balance','Stability','変動理由']} rows={[...(d.score_history||[])].reverse().map((x:any)=>[x.at?.replace('T',' ').slice(0,16),pt(x.condition),pt(x.balance),pt(x.stability),x.reason])}/></Panel><Logic mobileSection="details" d={d}/></MobileAnalysis>}
 {page==='balance'&&<BalanceView d={d} w={w} date={date} history={history} f={f}/>}
 {page==='stability'&&<StabilityView d={d} date={date} period={period} setPeriod={setPeriod} history={history} f={f}/>}
 {page==='subjects'&&<SubjectsView onSort={storageMode==='browser'?(value:MaterialSort)=>{void save({...d,profile:{...d.profile,material_sort:value}},'教材並び順');}:undefined} d={d} date={date} w={w} f={f}/>}
 {page==='materials'&&<MaterialsView onSort={storageMode==='browser'?(value:MaterialSort)=>{void save({...d,profile:{...d.profile,material_sort:value}},'教材並び順');}:undefined} d={d} date={date} w={w} f={f} onRecord={openManual} recordDisabled={saving||!!error||!!unsaved}/>}
 {page==='long'&&<LongView d={d} date={date} f={f}/>}
 {page==='goals'&&<MobileAnalysis><Panel title="目標を設定する" subtitle="Studyplusの目標とサイト独自の目標を分けて管理します。" action={<button onClick={openSettings}><Settings size={16}/>目標を編集</button>}><Stats items={[["Studyplus週間目標",f(d.goals.studyplus.weekly_total_minutes)],['サイト週間目標',f(d.goals.site.weekly_total_minutes)],['Learning Condition',`${pt(d.goals.site.learning_condition_target)} / 100`]]}/><p className="muted">サイト目標が未設定の場合のみ、Studyplus目標を週間集計に使用します。</p></Panel><GoalTable mobileSection="details" d={d} w={w} f={f}/><Panel mobileSection="analysis" title="教材別目標"><GridTable heads={['教材','週間目標','今週の実績','達成率','不足時間']} rows={d.materials.map(m=>{const n=A.total(A.records(d,w.start,date).filter(r=>r.material_id===m.id));return [m.name,f(m.weekly_target_minutes),f(n),pct(n,m.weekly_target_minutes),m.weekly_target_minutes?f(Math.max(0,m.weekly_target_minutes-n)):'—'];})}/></Panel><GoalHistory mobileSection="details" d={d}/></MobileAnalysis>}
 {page==='exams'&&<ExamsView d={d} date={date} save={save} saving={saving} f={f}/>}
