 const rows=sortMaterialRows<{m:any;rs:any[];last?:string;n7:number;p7:number;name:string;minutes:number}>(d.materials.map((m:any)=>{const rs=d.study_records.filter((r:any)=>A.validRecord(r)&&r.material_id===m.id&&r.date<=date),last=rs.map((r:any)=>r.date).sort().at(-1),n7=A.total(rs.filter((r:any)=>r.date>=A.addDays(date,-6))),p7=A.total(rs.filter((r:any)=>r.date>=A.addDays(date,-13)&&r.date<=A.addDays(date,-7)));return {m,rs,last,n7,p7,name:m.name,minutes:A.total(rs)};}),order);
