    {mobile?<><Stats lead={1} items={[groups[0].items[0],groups[1].items[0],groups[0].items[1],groups[0].items[3]]}/><div className="compact-trend"><h3>直近8週の学習推移</h3><Chart height={140} data={weeks.slice(-8)} series={[{key:'minutes',name:m.name}]}/></div>{onRecord&&<button className="primary entity-record" disabled={recordDisabled} onClick={()=>onRecord(m.id)}><Plus size={16}/>この教材で記録する</button>}<p className="summary-hint">全期間の推移は「推移」、目標・内訳・記録は「記録・詳細」へ</p></>:<MetricGroups groups={groups}/>}
